type FilterFn<T> = (item: T) => boolean;

function filterArray<T>(arr: T[], fn: FilterFn<T>): T[] {
  return arr.reduce<T[]>((acc, item) => {
    if (fn(item)) acc.push(item);
    return acc;
  }, []);
}

const nums = filterArray([1, 2, 3, 4, 5], n => n % 2 === 0);
